create table if not exists public.buildpulse_workforce_invitations(id uuid primary key default gen_random_uuid(),email text not null,token_hash text not null unique,role text not null check(role in ('admin','engineering','editorial','finance','advertising','moderation','support','analyst','contractor')),scopes text[] not null default '{}'::text[],worker_type text not null default 'employee' check(worker_type in ('employee','contractor','advisor')),department text,status text not null default 'pending' check(status in ('pending','accepted','revoked','expired')),expires_at timestamptz not null,created_by uuid not null references auth.users(id) on delete restrict,accepted_by uuid references auth.users(id) on delete set null,accepted_at timestamptz,created_at timestamptz not null default now());
alter table public.buildpulse_workforce_invitations enable row level security;revoke all on public.buildpulse_workforce_invitations from anon,authenticated;grant all on public.buildpulse_workforce_invitations to service_role;
create index if not exists idx_bp_workforce_invites_email_status on public.buildpulse_workforce_invitations(lower(email),status,expires_at);create index if not exists idx_bp_workforce_invites_creator on public.buildpulse_workforce_invitations(created_by,created_at desc);